import base64

def patch(filename, search_b64, replace_b64):
    with open(filename, 'r', encoding='utf-8') as f:
        content = f.read()
    
    search_str = base64.b64decode(search_b64).decode('utf-8')
    replace_str = base64.b64decode(replace_b64).decode('utf-8')
    
    content_norm = content.replace('\r\n', '\n')
    search_norm = search_str.replace('\r\n', '\n')
    
    if search_norm in content_norm:
        content_norm = content_norm.replace(search_norm, replace_str.replace('\r\n', '\n'))
        with open(filename, 'w', encoding='utf-8') as f:
            f.write(content_norm)
        print('Patched successfully.')
    else:
        print('Could not find target string.')

